Script.script:
--[[
    aardkit top-level command
    Sean Stoves, 2026-07-31
]]

aardkit = aardkit or {}
local U = aardkit.util

-- plugins register themselves here so 'aardkit' can list what's loaded
aardkit.plugins = aardkit.plugins or {}

function aardkit.register(name, desc, cmd)
    aardkit.plugins[name] = { desc = desc, cmd = cmd }
end

function aardkit.cmd(arg)
    local verb, rest = U.split_verb(arg)

    if verb == "" or verb == "help" or verb == "?" then
        local rows = {
            { "aardkit",        "this list" },
            { "aardkit plugins", "what's loaded" },
            { "aardkit stock",        "what we switch off in the stock AardwolfMudlet module" },
            { "aardkit probe",   "which Mudlet functions actually exist here" },
            { "panel",       "manage the docked/embedded windows" },
        }
        local names = {}
        for n in pairs(aardkit.plugins) do names[#names + 1] = n end
        table.sort(names)
        for _, n in ipairs(names) do
            rows[#rows + 1] = { n, aardkit.plugins[n].desc }
        end
        U.help("aardkit " .. aardkit.version, rows)

    elseif verb == "stock" then
        if aardkit.stock then aardkit.stock.cmd(rest) else U.warn("stock module handling isn't loaded.") end

    elseif verb == "probe" then
        -- Mudlet's Lua-side API isn't greppable in the binary, so ask the
        -- interpreter instead of guessing at it again
        local rows = {}
        for _, n in ipairs({
            "cecho", "decho", "hecho", "echoLink", "cechoLink", "dechoLink",
            "tempTimer", "killTimer", "tempRegexTrigger", "tempLineTrigger",
            "killTrigger", "registerAnonymousEventHandler", "killAnonymousEventHandler",
            "registerNamedTimer", "deleteNamedTimer",
            "deleteMap", "clearMap", "addRoom", "addAreaName", "setExit",
            "addSpecialExit", "setCustomEnvColor", "saveMap", "getRooms",
            "postHTTP", "getHTTP", "startLogging", "getProfileName",
        }) do
            rows[#rows + 1] = { n, type(_G[n]) }
        end
        rows[#rows + 1] = { "" }
        rows[#rows + 1] = { "db", type(db) }
        rows[#rows + 1] = { "db.create", type(db) == "table" and type(db.create) or "n/a" }
        rows[#rows + 1] = { "Geyser.Gauge", (Geyser and type(Geyser.Gauge)) or "nil" }
        rows[#rows + 1] = { "Adjustable.Container", (Adjustable and type(Adjustable.Container)) or "nil" }
        rows[#rows + 1] = { "table.save", type(table.save) }
        U.help("API probe", rows)

    elseif verb == "plugins" then
        local names = {}
        for n in pairs(aardkit.plugins) do names[#names + 1] = n end
        table.sort(names)
        if #names == 0 then
            U.note("Nothing registered.")
        else
            U.note(#names .. " loaded: " .. table.concat(names, ", "))
        end

    else
        local p = aardkit.plugins[verb]
        if p and p.cmd then p.cmd(rest) else U.warn("Unknown: aardkit " .. verb) end
    end
end
